import { useState, useCallback, useMemo } from 'react';
import { useMia } from '@/shared/contexts/MiaContext';
import {
  MiaChatHeader,
  MiaMessageList,
  MiaWelcome,
  MiaComposer
} from './';
import '../styles/mia-chat.css';

export default function MiaPage() {
  const {
    messages,
    sendMessage,
    isStreaming,
    conversations,
    activeConversationId,
    startNewConversation,
    executionSteps,
    abortStream,
    streamingText,
    streamingStatus,
    thinkingBlocks,
    agentRounds,
    activeTaskPlan,
    approveTaskPlan,
    cancelTaskPlan,
    answerClarification,
    pendingConfirmation,
    confirmPendingActions,
    cancelPendingActions,
  } = useMia();

  const [input, setInput] = useState('');

  const activeConversation = useMemo(() =>
    conversations.find(c => c.id === activeConversationId),
    [conversations, activeConversationId]
  );

  const handleSend = useCallback(() => {
    const text = input.trim();
    if (!text || isStreaming) return;
    setInput('');
    sendMessage(text);
  }, [input, isStreaming, sendMessage]);

  const handleSuggestion = useCallback((prompt: string) => {
    setInput('');
    sendMessage(prompt);
  }, [sendMessage]);

  return (
    <div className="flex h-[100dvh] w-full overflow-hidden bg-[--mia-bg] font-momma">
      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col relative min-w-0 bg-[--mia-bg]">
        {/* Header (Responsive) */}
        <MiaChatHeader
          conversationTitle={activeConversation?.title}
          onNewConversation={startNewConversation}
        />

        {/* Messages / Welcome View */}
        <MiaMessageList
          messages={messages}
          isStreaming={isStreaming}
          streamingText={streamingText}
          streamingStatus={streamingStatus}
          thinkingBlocks={thinkingBlocks}
          agentRounds={agentRounds}
          executionSteps={executionSteps}
          activeTaskPlan={activeTaskPlan}
          pendingConfirmation={pendingConfirmation}
          onConfirm={confirmPendingActions}
          onCancelConfirm={cancelPendingActions}
          onApproveTask={approveTaskPlan}
          onCancelTask={cancelTaskPlan}
          onClarificationAnswer={answerClarification}
          emptyState={<MiaWelcome onSelectSuggestion={handleSuggestion} />}
        />

        {/* ── Composer fixo no bottom ── */}
        <div className="sticky bottom-0 left-0 right-0 z-10">
          {/* Fade sobre as mensagens */}
          <div className="h-10 bg-gradient-to-t from-[--mia-bg] to-transparent pointer-events-none" />

          <div className="bg-[--mia-bg] px-3 sm:px-6 pb-4 pt-0">
            <div className="max-w-2xl mx-auto">
              <MiaComposer
                value={input}
                onChange={setInput}
                onSend={handleSend}
                onStop={abortStream}
                isStreaming={isStreaming}
                disabled={false}
              />
              <p className="mt-2 text-center text-[10px] text-[--mia-text-muted]/60">
                A MIA pode cometer erros — verifique informações importantes.
              </p>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

