// Toda a lógica foi movida para src/features/mia/model/useMia.ts (US-024)
//
// MIA 2.0 Glass-Box: adicionado MiaGlassBoxContext (paralelo, não modifica
// useMia.ts existente). Consumers do glass-box usam useMiaGlassBoxContext().
//
// Stream bridge (useMiaGlassBoxStreamBridge) é montado dentro do provider
// pra observar useMia state e popular watchLog em tempo real.

import React, { createContext, useContext, ReactNode } from 'react';
import { useMia as useMiaHook, type UseMiaReturn, type MiaConversation } from '@/features/mia/model';
import { useMiaGlassBox, type UseMiaGlassBoxReturn } from '@/features/mia/model/useMiaGlassBox';
import { useMiaGlassBoxStreamBridge } from '@/features/mia/hooks/useMiaGlassBoxStreamBridge';
import { useMiaGlassBoxContextInjector } from '@/features/mia/hooks/useMiaGlassBoxContextInjector';

// Re-export do tipo MiaConversation para consumers que o importam daqui
export type { MiaConversation };

// ============================================================================
// CONTEXTS
// ============================================================================

const MiaContext = createContext<UseMiaReturn | undefined>(undefined);
const MiaGlassBoxContext = createContext<UseMiaGlassBoxReturn | undefined>(undefined);

// ============================================================================
// PROVIDER — combina hooks useMia + useMiaGlassBox + bridge
// ============================================================================

/**
 * Inner — roda dentro dos providers pra conseguir consumir ambos os contexts.
 * Wireup das observações useMia → watchLog acontece aqui.
 */
function MiaProviderInner({ children }: { children: ReactNode }) {
  useMiaGlassBoxStreamBridge();
  useMiaGlassBoxContextInjector();
  return <>{children}</>;
}

export function MiaProvider({ children }: { children: ReactNode }) {
  const miaValue = useMiaHook();
  const glassBoxValue = useMiaGlassBox();
  return (
    <MiaContext.Provider value={miaValue}>
      <MiaGlassBoxContext.Provider value={glassBoxValue}>
        <MiaProviderInner>{children}</MiaProviderInner>
      </MiaGlassBoxContext.Provider>
    </MiaContext.Provider>
  );
}

// ============================================================================
// CONSUMER HOOKS
// ============================================================================

export function useMia(): UseMiaReturn {
  const context = useContext(MiaContext);
  if (!context) throw new Error('useMia must be used within a MiaProvider');
  return context;
}

/**
 * Hook para acessar estado do MIA 2.0 Glass-Box (Modo IA toggle, watch log,
 * Page Models, highlights, autonomia). Coexiste com useMia() — não substitui.
 *
 * Uso típico:
 *   const { miaModeEnabled, toggleMiaMode } = useMiaGlassBoxContext();
 */
export function useMiaGlassBoxContext(): UseMiaGlassBoxReturn {
  const context = useContext(MiaGlassBoxContext);
  if (!context) throw new Error('useMiaGlassBoxContext must be used within a MiaProvider');
  return context;
}

