/**
 * MiaInlineChat — Chat da Mia renderizado inline como página do dashboard.
 *
 * Usa EXATAMENTE a mesma estrutura, componentes e dinâmicas da antiga rota
 * `/mia` (MiaPage.tsx): MiaChatHeader, MiaMessageList (com agentRounds,
 * thinkingBlocks, executionSteps, task plans, confirmations), MiaComposer,
 * MiaWelcome, MIA v2 toggle + reasoning mode.
 *
 * Diferença: traz a Mia para o design system Momma — fundo branco com faixa
 * de toldo, ícones decorativos animados, ambient glows e tipografia serif
 * sofisticada. A classe `mia-momma-surface` redefine as vars `--mia-bg*` para
 * serem transparentes, deixando os componentes internos herdarem o novo visual.
 */
import { useState, useCallback, useMemo } from 'react';
import { useMia } from '@/shared/contexts/MiaContext';
import {
  MiaChatHeader,
  MiaMessageList,
  MiaWelcome,
  MiaComposer,
} from './';
import { MiaAnnouncementsBanner } from '@/features/announcements';
import { Leaf, MessageCircle, Sparkles } from 'lucide-react';
import '../styles/mia-chat.css';

export function MiaInlineChat() {
  const {
    messages,
    sendMessage,
    isStreaming,
    conversations,
    activeConversationId,
    startNewConversation,
    executionSteps,
    abortStream,
    streamingText,
    streamingStatus,
    thinkingBlocks,
    agentRounds,
    activeTaskPlan,
    approveTaskPlan,
    cancelTaskPlan,
    answerClarification,
    pendingConfirmation,
    confirmPendingActions,
    cancelPendingActions,
  } = useMia();

  const [input, setInput] = useState('');

  const activeConversation = useMemo(
    () => conversations.find((c) => c.id === activeConversationId),
    [conversations, activeConversationId],
  );

  const handleSend = useCallback(() => {
    const text = input.trim();
    if (!text || isStreaming) return;
    setInput('');
    sendMessage(text);
  }, [input, isStreaming, sendMessage]);

  const handleSuggestion = useCallback(
    (prompt: string) => {
      setInput('');
      sendMessage(prompt);
    },
    [sendMessage],
  );

  return (
    <div className="mia-momma-surface h-full w-full max-h-full bg-white dark:bg-[#0A0A0A] font-sans relative overflow-hidden transition-colors duration-300 flex flex-col">
      {/* Faixa de toldo Momma no topo */}
      <div
        className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 shadow-sm pointer-events-none"
        aria-hidden="true"
      />

      {/* Ícones decorativos animados de fundo — GOLD DOURADO ALARANJADO
